            continue
        found = True
        relative = path.relative_to(root).as_posix()
        content = path.read_bytes()
        normalized = DOMAIN_SDK_BUILD_CONSTRAINT_BYTES.sub(
            b"domainry_domain_sdk_<identity>", content,
        )

