// This file is initial project-owned business source. Domainry will never overwrite it.
package field_service

import (
	"context"
	"encoding/json"
	capabilities "example.com/domainry/m2-field-service/generated/capabilities"
	"example.com/domainry/m2-field-service/generated/data"
	"example.com/domainry/m2-field-service/generated/schema"
	"fmt"
	"strconv"
	"strings"
	"time"
)

type requestedPartUsage struct {
	PartID   string `json:"part_id"`
	Quantity int64  `json:"quantity"`
}

func moneyCents(value string) (int64, error) {
	value = strings.TrimSpace(value)
	if value == "" || strings.HasPrefix(value, "-") || strings.HasPrefix(value, "+") {
		return 0, fmt.Errorf("invalid money")
	}
	parts := strings.Split(value, ".")
	if len(parts) > 2 || parts[0] == "" || (len(parts) == 2 && len(parts[1]) > 2) {
		return 0, fmt.Errorf("invalid money")
	}
	whole, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil || whole > (1<<63-1)/100 {
		return 0, fmt.Errorf("invalid money")
	}
	fraction := int64(0)
	if len(parts) == 2 && parts[1] != "" {
		fractionText := parts[1]
		if len(fractionText) == 1 {
			fractionText += "0"
		}
		fraction, err = strconv.ParseInt(fractionText, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("invalid money")
		}
	}
	return whole*100 + fraction, nil
}

func moneyString(cents int64) string {
	return fmt.Sprintf("%d.%02d", cents/100, cents%100)
}

// CompleteAtomicRepair implements the project-owned work_order.complete_atomic_repair Handler.
func CompleteAtomicRepair(ctx context.Context, caps capabilities.CompleteAtomicRepairCapabilities, input capabilities.CompleteAtomicRepairInput) (capabilities.CompleteAtomicRepairOutput, error) {
	if caps.Execution == nil || caps.Part == nil || caps.PartUsage == nil || caps.WorkOrder == nil || input.CompletionKey == "" {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.invalid_completion"}
	}
	quotedCents, err := moneyCents(string(input.QuotedAmount))
	if err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.invalid_quoted_amount"}
	}
	var requested []requestedPartUsage
	if err := json.Unmarshal([]byte(input.PartUsagesJson), &requested); err != nil || len(requested) == 0 || len(requested) > 200 {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.invalid_part_usages"}
	}
	partIDs := make([]schema.PartID, 0, len(requested))
	seen := make(map[string]struct{}, len(requested))
	for _, usage := range requested {
		if usage.PartID == "" || usage.Quantity <= 0 {
			return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.invalid_part_usage"}
		}
		if _, exists := seen[usage.PartID]; exists {
			return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.duplicate_part_usage"}
		}
		seen[usage.PartID] = struct{}{}
		partIDs = append(partIDs, schema.PartID(usage.PartID))
	}
	principal := caps.Execution.Principal()
	order, err := caps.WorkOrder.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, err
	}
	if !principal.Known || order.AssignedTechnicianUser == nil || string(order.AssignedTechnicianUser.ID()) != principal.UserID {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.not_assigned_technician"}
	}
	if order.Status != schema.WorkOrderStatus("in_repair") {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.not_in_repair"}
	}
	parts, err := caps.Part.GetForUpdateBatch(ctx, partIDs)
	if err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, err
	}
	if len(parts) != len(requested) {
		return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.part_not_found"}
	}
	byID := make(map[schema.PartID]schema.Part, len(parts))
	for _, part := range parts {
		byID[part.ID] = part
	}
	partMutations := make([]data.PartUpdateMutation, 0, len(requested))
	usageCreates := make([]schema.CreatePartUsage, 0, len(requested))
	now := time.Now().UTC()
	for _, request := range requested {
		part, ok := byID[schema.PartID(request.PartID)]
		if !ok {
			return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "work_order.part_not_found"}
		}
		if part.StockQuantity < request.Quantity {
			return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "inventory.insufficient_stock"}
		}
		unitCents, priceErr := moneyCents(string(part.UnitPrice))
		if priceErr != nil || (request.Quantity != 0 && unitCents > (1<<63-1)/request.Quantity) {
			return capabilities.CompleteAtomicRepairOutput{}, &capabilities.BusinessError{Code: "inventory.invalid_unit_price"}
		}
		partMutations = append(partMutations, data.NewPartUpdate(part.ID).
			SetStockQuantity(part.StockQuantity-request.Quantity).
			RequireStockQuantityAtLeast(request.Quantity, "inventory.insufficient_stock").
			WithExpectedUpdatedAt(part.UpdatedAt))
		usageCreates = append(usageCreates, schema.CreatePartUsage{
			CompletionKey:     input.CompletionKey,
			LineAmount:        schema.PartUsageLineAmount(moneyString(unitCents * request.Quantity)),
			OccurredAt:        now,
			PartID:            schema.NewPartUsagePartIDReference(part.ID),
			Quantity:          request.Quantity,
			UnitPriceSnapshot: schema.PartUsageUnitPriceSnapshot(moneyString(unitCents)),
			WorkOrderID:       schema.NewPartUsageWorkOrderIDReference(order.ID),
		})
	}
	if _, err = caps.Part.ConditionalUpdateBatch(ctx, partMutations); err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, err
	}
	if _, err = caps.PartUsage.CreateBatch(ctx, usageCreates); err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, err
	}
	final := schema.WorkOrderFinalAmount(moneyString(quotedCents))
	orderMutation := data.NewWorkOrderUpdate(order.ID).
		SetQuotedAmount(schema.WorkOrderQuotedAmount(moneyString(quotedCents))).
		SetFinalAmount(final).
		SetCompletionIdempotencyKey(input.CompletionKey).
		SetCompletedAt(now).
		SetStatus(schema.WorkOrderStatus("completed")).
		RequireStatusEqual(schema.WorkOrderStatus("in_repair"), "work_order.not_in_repair").
		RequireAssignedTechnicianUserEqual(*order.AssignedTechnicianUser, "work_order.not_assigned_technician").
		RequireCompletionIdempotencyKeyNull("work_order.already_completed").
		WithExpectedUpdatedAt(order.UpdatedAt)
	updated, err := caps.WorkOrder.ConditionalUpdate(ctx, orderMutation)
	if err != nil {
		return capabilities.CompleteAtomicRepairOutput{}, err
	}
	return capabilities.CompleteAtomicRepairOutput{FinalAmount: *updated.FinalAmount, UsageCount: int64(len(usageCreates)), WorkOrderID: updated.ID}, nil
}

