// This file is initial project-owned business source. Domainry will never overwrite it.
package field_service

import (
	"context"
	capabilities "example.com/domainry/m2-field-service/generated/capabilities"
	"example.com/domainry/m2-field-service/generated/data"
	"example.com/domainry/m2-field-service/generated/schema"
	"time"
)

// ScanOverdueReminders implements the project-owned work_order.scan_overdue_reminders Handler.
func ScanOverdueReminders(ctx context.Context, caps capabilities.ScanOverdueRemindersCapabilities, input capabilities.ScanOverdueRemindersInput) (capabilities.ScanOverdueRemindersOutput, error) {
	if caps.Execution == nil || caps.ReminderReceipt == nil || caps.WorkOrder == nil || caps.Notifications == nil || input.RunDate.IsZero() {
		return capabilities.ScanOverdueRemindersOutput{}, &capabilities.BusinessError{Code: "reminder.invalid_scan"}
	}
	businessDate := time.Date(input.RunDate.UTC().Year(), input.RunDate.UTC().Month(), input.RunDate.UTC().Day(), 0, 0, 0, 0, time.UTC)
	cutoff := businessDate.Add(-48 * time.Hour).Format(time.RFC3339)
	orders, err := caps.WorkOrder.List(ctx, data.NewWorkOrderQuery().
		WhereStatusEqual(schema.WorkOrderStatus("dispatched")).
		WhereCreatedAtLessThanOrEqual(cutoff).
		OrderByIDAscending().Page(1, 200))
	if err != nil {
		return capabilities.ScanOverdueRemindersOutput{}, err
	}
	queries := make([]data.ReminderReceiptQuery, 0, len(orders))
	candidates := make([]schema.WorkOrder, 0, len(orders))
	dedupeKeys := make([]string, 0, len(orders))
	dateText := businessDate.Format("2006-01-02")
	for _, order := range orders {
		if order.AssignedTechnicianUser == nil {
			continue
		}
		key := string(order.ID) + ":" + dateText
		queries = append(queries, data.NewReminderReceiptQuery().WhereDedupeKeyEqual(key))
		candidates = append(candidates, order)
		dedupeKeys = append(dedupeKeys, key)
	}
	if len(candidates) == 0 {
		return capabilities.ScanOverdueRemindersOutput{}, nil
	}
	existing, err := caps.ReminderReceipt.ExistsBatch(ctx, queries)
	if err != nil {
		return capabilities.ScanOverdueRemindersOutput{}, err
	}
	creates := make([]schema.CreateReminderReceipt, 0, len(candidates))
	intents := make([]capabilities.ScanOverdueRemindersNotificationIntent, 0, len(candidates))
	for i, order := range candidates {
		if existing[i] {
			continue
		}
		recipient := string(order.AssignedTechnicianUser.ID())
		creates = append(creates, schema.CreateReminderReceipt{
			BusinessDate: businessDate, DedupeKey: dedupeKeys[i], RecipientUser: recipient,
			WorkOrderID: schema.NewReminderReceiptWorkOrderIDReference(order.ID),
		})
		intents = append(intents, capabilities.ScanOverdueRemindersNotificationIntent{
			EventType: "work_order.overdue", SourceEventID: "overdue:" + dedupeKeys[i],
			RecipientUserIDs: []string{recipient}, Surface: "business_workspace",
			SubjectObjectKey: "work_order", SubjectRecordID: string(order.ID), SubjectVersion: order.UpdatedAt,
			DedupeKey: "work_order.overdue:" + dedupeKeys[i], GroupKey: string(order.ID), OccurredAt: time.Now().UTC(),
		})
	}
	if len(creates) == 0 {
		return capabilities.ScanOverdueRemindersOutput{}, nil
	}
	if _, err = caps.ReminderReceipt.CreateBatch(ctx, creates); err != nil {
		return capabilities.ScanOverdueRemindersOutput{}, err
	}
	if _, err = caps.Notifications.DispatchBatch(ctx, intents); err != nil {
		return capabilities.ScanOverdueRemindersOutput{}, err
	}
	return capabilities.ScanOverdueRemindersOutput{ReminderCount: int64(len(creates))}, nil
}
