    spans = todo_section_spans(todo.read_text(encoding="utf-8"))
    return {
        "contract_version": REQUIREMENTS_ENTRY_VERSION,
        "state": "ready",
        "stage": "requirements_domain_truth",
        "agent_should_stop": False,
        "reads_before_entry": [],
        "todo": str(todo),
        "todo_edit_scope": {
            "header_ends_before_line": min(
                (value["start_line"] for value in spans.values()), default=1,
            ),
            "sections": {
                key: spans[key] for key in ("requirements", "domain_truth_design")
                if key in spans
            },
        },
        "frontend_evidence": frontend,
        "authority_route": stage_authority_route("requirements"),
        "recipe": [
            {"action": "verify_embedded_cli", "argv": [str(cli), "version", "--json"]},
