            {"action": "list_requirements_gates", "argv": [*prefix, "list", "--stage", "requirements"]},
            {"action": "list_domain_truth_gates", "argv": [*prefix, "list", "--stage", "domain_truth_design"]},
            {
                "action": "bind_current_requirements_artifact",
                "argv_template": [
