def preflight_workflow_init(
    project: Path, session: str, cli: Path, started_epoch_ms: int,
) -> tuple[dict | None, dict | None]:
    todo = project / ".domainry" / "development" / f"{session}.md"
    state = state_path(project, session)
    if state.exists() or state.is_symlink():
        if not todo.exists() or todo.is_symlink() or not todo.is_file():
            return None, workflow_repair(
                project, session, cli, "gate_ledger_without_todo",
                "session Gate ledger exists but its canonical regular TODO is missing",
            )
        content = todo.read_text(encoding="utf-8")
        identity = re.search(r"^Agent session ID:\s*(\S*)\s*$", content, re.MULTILINE)
        if identity and identity.group(1) and identity.group(1) != session:
            return None, workflow_repair(
                project, session, cli, "todo_session_identity_conflict",
                f"TODO declares session {identity.group(1)!r}, expected {session!r}",
            )
        try:
            discover_gates(content)
            load_state(project, session)
        except (GateError, json.JSONDecodeError) as error:
            return None, workflow_repair(
                project, session, cli, "gate_ledger_identity_or_contract_conflict", str(error),
            )
        current = CURRENT_STAGE.search(content)
        return {
            "todo": todo, "todo_content": content, "todo_created": False,
            "stage_document": None,
            "stage_result": {"state": "existing_managed_state"},
            "stage_write": False,
            "frontend": frontend_source_inventory(project),
            "current_stage": current.group(1) if current else "unknown",
        }, None
    if todo.exists() or todo.is_symlink():
        if todo.is_symlink() or not todo.is_file():
            return None, workflow_repair(
                project, session, cli, "todo_path_unsafe",
                "session TODO path is not a regular non-symlink file",
            )
        content = todo.read_text(encoding="utf-8")
        identity = re.search(r"^Agent session ID:\s*(\S*)\s*$", content, re.MULTILINE)
        if identity and identity.group(1) and identity.group(1) != session:
            return None, workflow_repair(
                project, session, cli, "todo_session_identity_conflict",
                f"TODO declares session {identity.group(1)!r}, expected {session!r}",
            )
        current = CURRENT_STAGE.search(content)
        if not current:
            return None, workflow_repair(
                project, session, cli, "todo_current_stage_missing",
                "session TODO has no canonical Current stage field",
            )
        try:
            discover_gates(content)
        except GateError as error:
            return None, workflow_repair(
                project, session, cli, "todo_gate_contract_invalid", str(error),
            )
        todo_content = content
        todo_created = False
    else:
        if state.exists() or state.is_symlink():
            return None, workflow_repair(
                project, session, cli, "gate_ledger_without_todo",
                "session Gate ledger exists but its canonical TODO is missing",
            )
        frontend = frontend_source_inventory(project)
        todo_content = instantiate_workflow_todo(
            Path(__file__).resolve().parents[1], session, frontend["state"] == "present",
        )
        todo_created = True
    stage_document, stage_result, stage_write = prepare_stage_timing(
        project, started_epoch_ms, session,
    )
    if stage_document is None:
        return None, workflow_repair(
            project, session, cli, stage_result["reason_code"], stage_result["diagnosis"],
        )
    if not todo_created and not state.exists() and stage_result["state"] == "current":
        current = CURRENT_STAGE.search(todo_content)
        if current and current.group(1) == "requirements":
            attempts = stage_document.get("stages", {}).get("requirements", {}).get("attempts", [])
            if not attempts:
                return None, workflow_repair(
                    project, session, cli, "todo_stage_ledger_identity_conflict",
                    "requirements TODO exists but current stages v2 has no requirements attempt",
                )
    return {
        "todo": todo,
        "todo_content": todo_content,
        "todo_created": todo_created,
        "stage_document": stage_document,
        "stage_result": stage_result,
        "stage_write": stage_write,
        "frontend": frontend_source_inventory(project),
        "current_stage": (
            CURRENT_STAGE.search(todo_content).group(1)
            if CURRENT_STAGE.search(todo_content) else "unknown"
        ),
    }, None


